import{_ as t,o as l,c as o,a2 as r}from"./chunks/framework.D6V-51XQ.js";const p=JSON.parse('{"title":"Level system (100 levels)","description":"","frontmatter":{},"headers":[],"relativePath":"guide/level-system.md","filePath":"guide/level-system.md"}'),s={name:"guide/level-system.md"};function d(a,e,i,n,c,h){return l(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="level-system-100-levels" tabindex="-1">Level system (100 levels) <a class="header-anchor" href="#level-system-100-levels" aria-label="Permalink to &quot;Level system (100 levels)&quot;">​</a></h1><p>The 100 levels of the game are planned, drawn and built by a small pipeline. The design sheet <strong><code>design/level-system.xlsx</code></strong> holds the criteria, the level table and the image descriptions.</p><h2 id="pipeline" tabindex="-1">Pipeline <a class="header-anchor" href="#pipeline" aria-label="Permalink to &quot;Pipeline&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Step</th><th>Command</th><th>Output</th></tr></thead><tbody><tr><td>Plan (roles, targets, pairs, colours)</td><td><code>tools/level-plan.ts</code></td><td>used by the steps below</td></tr><tr><td>Drawings</td><td><code>npm run art</code> (keeps existing files; <code>-- --force</code> overwrites)</td><td><code>art/levels/NNN_&lt;subject&gt;.svg</code></td></tr><tr><td>Order drawings by structure</td><td><code>npm run art:measure</code></td><td>prints the pool order (simple → structured)</td></tr><tr><td>Build levels</td><td><code>npm run levels:build</code> (or <code>-- 12 37</code> for some levels)</td><td><code>levels/NNN-&lt;subject&gt;.json</code>, collection <strong>Main</strong>, <code>design/level-report.json</code></td></tr><tr><td>Design sheet</td><td><code>python3 tools/export-sheet.py</code></td><td><code>design/level-system.xlsx</code></td></tr></tbody></table><p><strong>Replacing a picture:</strong> edit or replace <code>art/levels/NNN_&lt;subject&gt;.svg</code> (any vector tool), then run <code>npm run levels:build -- NNN</code> and <code>python3 tools/export-sheet.py</code>. Don&#39;t run <code>npm run art -- --force</code> afterwards: it would overwrite hand-made SVGs with the built-in drawings.</p><h2 id="difficulty-score" tabindex="-1">Difficulty score <a class="header-anchor" href="#difficulty-score" aria-label="Permalink to &quot;Difficulty score&quot;">​</a></h2><p>0–100, the same formula in the game, the editor and the sheet (<code>src/core/difficulty.ts</code>):</p><table tabindex="0"><thead><tr><th>Criterion</th><th>Measured as</th><th>Range (0 → full)</th><th>Weight</th></tr></thead><tbody><tr><td>Pairs</td><td>number of pairs</td><td>3 → 45</td><td>30%</td></tr><tr><td>Blocking depth</td><td>rounds when every open pair is cleared each round</td><td>1 → 6</td><td>30%</td></tr><tr><td>Trap share</td><td>dots that would bump something if tapped first</td><td>0 → 60%</td><td>30%</td></tr><tr><td>Colours</td><td>distinct colours</td><td>2 → 12</td><td>10%</td></tr></tbody></table><h2 id="rules" tabindex="-1">Rules <a class="header-anchor" href="#rules" aria-label="Permalink to &quot;Rules&quot;">​</a></h2><ul><li>Level 1 = tap tutorial. From level 2, blocks of 5: slot 1 <strong>relax</strong>, slot 3 <strong>hard</strong>, slots 2/4/5 <strong>normal</strong> (relax 2, 7, 12, …; hard 4, 9, 14, 19, …).</li><li>Relax is easier than every normal of its block (level 2 is the collision tutorial and has one block).</li><li>Hard levels 4, 9, 14 are only a little harder than their block and the previous hard level. From <strong>level 19</strong> hard levels are really hard: base + 20 (max 85).</li><li>Targets: normal 10 → 55, relax = normal − 8. The builder picks, for every level, the layout closest to the target that also respects the rules, sweeping the generator&#39;s difficulty dial (dots placed on crossing lines) and ±25% pairs.</li><li><strong>Big dots</strong> only on strokes marked <code>data-big=&quot;1&quot;</code> in the SVG: one accent pair on relax levels, sometimes a blocker on hard levels. Never sprinkled.</li><li>Tutorials: level 1 tap, level 2 bumping, level 8 pinch zoom. Hard slots show the &quot;Hard&quot; label.</li></ul><h2 id="drawing-rules-svg" tabindex="-1">Drawing rules (SVG) <a class="header-anchor" href="#drawing-rules-svg" aria-label="Permalink to &quot;Drawing rules (SVG)&quot;">​</a></h2><ul><li>A stroke that <strong>ends exactly on</strong> another stroke is a T-junction: its dot blocks that stroke.</li><li>Crossing strokes don&#39;t block, unless the generator puts a dot on the crossing (difficulty dial).</li><li>Never let two strokes overlap along an edge (e.g. two rectangles sharing a side).</li><li>Supported elements: <code>path</code> (M L H V C S Q T Z), <code>line</code>, <code>polyline</code>, <code>polygon</code>, <code>rect</code>, <code>circle</code>, <code>ellipse</code>; no transforms. Canvas 400 × 400.</li></ul>',12)])])}const g=t(s,[["render",d]]);export{p as __pageData,g as default};
